#!/bin/bash
# the S4 bench (from S3's): ONE page (test&scene=12, the fake), q pinned, 8 s warm, a cold call discarded, then 3 interleaved quads of the SUBSTRATE
# benchFluid(300,null,'pool') / bands ship (K2 default: NOISE_V .02 on the fake's high .35 — the branch taken at a small amplitude) / bands with the grain
# OFF (NOISE_V 0: the branch not taken) / bands with the grain held at NOISE_V 1 and MS.high 1 (the hash on every texel of the velocity pass at full
# amplitude) — then the SHOW pass: CARD.bench(12,300) (FLUID's) / bench(13,300) (FLUID2's with the specular at highS 1) ×3 interleaved, bench(0) beside
cd /home/toma/Documents/Kraftek/RetinaRave-wt-fluid2 || exit 1
E='{"eval":"CARD.benchFluid(300,null,\"pool\").toFixed(3)+\" pool\""},{"eval":"(CARD.fluid.K2.NOISE_V=1,CARD.MS.high=0.35,CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" ship \"+JSON.stringify(CARD.fluid.highs))"},{"eval":"(CARD.fluid.K2.NOISE_V=0,CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" grain-off\")"},{"eval":"(CARD.fluid.K2.NOISE_V=1,CARD.MS.high=1,CARD.fluid.K2.NOISE_CELL=1,CARD.fluid.K2.NOISE_HOLD=1,CARD.benchFluid(300,null,\"bands\").toFixed(3)+\" grain-1-cell1 \"+JSON.stringify(CARD.fluid.highs))"}'
S='{"eval":"(CARD.MS.highS=0,CARD.bench(12,300).toFixed(3)+\" show12\")"},{"eval":"(CARD.MS.highS=1,CARD.MS.high=1,CARD.bench(13,300).toFixed(3)+\" show13-highS1-grain \"+CARD.REG[13].scene.hooks.flinfo())"},{"eval":"(CARD.REG[13].scene.SPEC.GRAIN=0,CARD.bench(13,300).toFixed(3)+\" show13-grain0\")"},{"eval":"(CARD.REG[13].scene.SPEC.GRAIN=1,CARD.bench(13,300).toFixed(3)+\" show13-grain1\")"}'
GPU=1 PORT=8975 OUT=tools/work node tools/cdp.js "test&scene=12" "[{\"until\":\"window.CARD\"},{\"eval\":\"setInterval(()=>CARD.Q.q=0.95,16);'pinned'\"},{\"wait\":8000},{\"eval\":\"CARD.benchFluid(300,null,'pool').toFixed(3)+' cold'\"},$E,$E,$E,{\"eval\":\"(CARD.fluid.K2.NOISE_V=0.02,CARD.MS.high=0.35,'reset')\"},$S,$S,$S,{\"eval\":\"CARD.bench(0,300).toFixed(3)+' nav'\"},{\"eval\":\"JSON.stringify({tier:CARD.fluid.tier,sim:[CARD.fluid.simW,CARD.fluid.simH],dye:[CARD.fluid.dyeW,CARD.fluid.dyeH],q:CARD.Q.q,g:CARD.fluid.grammar,errs:CARD.ERRS})\"}]" 2>&1 | grep -E "^EVAL|EXC|ERR" | sed 's/^EVAL //'
uptime
echo "== MOBILE=1 tier 0: scene 13 alive + the substrate bench at tier 0 (ship / grain off / grain 1) + the show pass (13 at highS 1 and 0, 12)"
MOBILE=1 GPU=1 PORT=8975 OUT=tools/work node tools/cdp.js "test&scene=13" "[{\"until\":\"window.CARD\"},{\"wait\":4000},{\"eval\":\"JSON.stringify({sc:CARD.SC.cur,g:CARD.fluid.grammar,tier:CARD.fluid.tier,sim:[CARD.fluid.simW,CARD.fluid.simH],dye:[CARD.fluid.dyeW,CARD.fluid.dyeH],errs:CARD.ERRS,bad:CARD.nonFinite(),frameN:CARD.frameN,highs:CARD.fluid.highs,flinfo:CARD.REG[13].scene.hooks.flinfo()})\"},{\"eval\":\"CARD.benchFluid(300,null,'bands').toFixed(3)+' bands ship'\"},{\"eval\":\"(CARD.fluid.K2.NOISE_V=0,CARD.benchFluid(300,null,'bands').toFixed(3)+' bands grain-off')\"},{\"eval\":\"(CARD.fluid.K2.NOISE_V=1,CARD.MS.high=1,CARD.benchFluid(300,null,'bands').toFixed(3)+' bands grain-1')\"},{\"eval\":\"(CARD.fluid.K2.NOISE_V=0.02,CARD.benchFluid(300,null,'pool').toFixed(3)+' pool')\"},{\"eval\":\"(CARD.MS.highS=1,CARD.bench(13,300).toFixed(3)+' show13-highS1')\"},{\"eval\":\"(CARD.MS.highS=0,CARD.bench(13,300).toFixed(3)+' show13-highS0')\"},{\"eval\":\"CARD.bench(12,300).toFixed(3)+' show12'\"},{\"eval\":\"(CARD.MS.highS=1,CARD.bench(13,300).toFixed(3)+' show13-highS1 b')\"},{\"eval\":\"CARD.bench(12,300).toFixed(3)+' show12 b'\"},{\"shot\":\"s4-mobile-s13\"},{\"eval\":\"JSON.stringify({errs:CARD.ERRS,bad:CARD.nonFinite(),tier:CARD.fluid.tier})\"}]" 2>&1 | grep -E "^EVAL|EXC|ERR" | sed 's/^EVAL //'
